//! The wow-api declarations embedded in the compiler (decision T83), until
//! the package manager provides `wow-api-<flavor>` packages (milestone M6).
//! Generated by `cargo xtask types gen`; see `data/`.

use std::collections::{HashMap, HashSet};

/// A generated declaration file.
#[derive(Clone, Copy, Debug)]
pub struct File {
    pub path: &'static str,
    /// The declarations to parse: the file in `data/` with its globals of a
    /// primitive type replaced by spaces (`build.rs`).
    pub text: &'static str,
    /// Those globals, in file order.
    pub globals: Globals,
}

/// The type of a global taken out of the parsed text.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Prim {
    Any,
    Boolean,
    Number,
    String,
    Table,
}

/// One `declare global NAME: <primitive>`, with its `@onDemand` addon.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SimpleGlobal {
    pub name: &'static str,
    pub ty: Prim,
    pub on_demand: Option<&'static str>,
}

/// A file's globals of a primitive type, in file order (generated by
/// `build.rs`). No other declaration of the file declares the same names.
#[derive(Clone, Copy, Debug, Default)]
pub struct Globals {
    /// The names, separated by `\n`.
    names: &'static str,
    /// Per name, its `Prim` as a digit.
    types: &'static [u8],
    /// The `@onDemand` addons, by index into the names.
    on_demand: &'static [(u32, &'static str)],
}

impl Globals {
    pub fn len(&self) -> usize {
        self.types.len()
    }

    pub fn is_empty(&self) -> bool {
        self.types.is_empty()
    }

    pub fn iter(&self) -> impl Iterator<Item = SimpleGlobal> + 'static {
        let names = self.names.split('\n').filter(|n| !n.is_empty());
        let mut on_demand = self.on_demand.iter().peekable();
        names
            .zip(self.types.iter().copied())
            .enumerate()
            .map(move |(i, (name, ty))| SimpleGlobal {
                name,
                ty: match ty {
                    b'0' => Prim::Any,
                    b'1' => Prim::Boolean,
                    b'2' => Prim::Number,
                    b'3' => Prim::String,
                    _ => Prim::Table,
                },
                on_demand: on_demand
                    .next_if(|(at, _)| *at as usize == i)
                    .map(|(_, a)| *a),
            })
    }
}

macro_rules! api_file {
    ($name:literal) => {
        File {
            path: concat!("<wow-api>/", $name, ".d.wowlua"),
            text: include_str!(concat!(env!("OUT_DIR"), "/", $name, ".d.wowlua")),
            globals: include!(concat!(env!("OUT_DIR"), "/", $name, ".globals.rs")),
        }
    };
}

const SHARED: File = api_file!("shared");

/// The declarations of a flavor: the shared file and the flavor's own.
pub fn declarations(flavor: &str) -> Option<[File; 2]> {
    own(flavor).map(|own| [SHARED, own])
}

/// The declarations every flavor shares.
pub fn shared() -> File {
    SHARED
}

/// A flavor's own declarations, next to [`shared`].
pub fn own(flavor: &str) -> Option<File> {
    Some(match flavor {
        "standard" => api_file!("standard"),
        "camelot" => api_file!("camelot"),
        "tbc" => api_file!("tbc"),
        "mists" => api_file!("mists"),
        "vanilla" => api_file!("vanilla"),
        _ => return None,
    })
}

/// What a flavor's tooltips offer (spec stdlib "tooltip"): the
/// `Enum.TooltipDataType` names, and whether the client has the tooltip
/// data system (`C_TooltipInfo`).
#[derive(Clone, Debug)]
pub struct TooltipInfo {
    pub kinds: Vec<String>,
    pub data_system: bool,
}

pub fn tooltip_info(flavor: &str) -> Option<TooltipInfo> {
    let [_, own] = declarations(flavor)?;
    let mut kinds = Vec::new();
    let mut inside = false;
    for line in own.text.lines() {
        if line == "    namespace TooltipDataType" {
            inside = true;
        } else if inside && line == "    end" {
            break;
        } else if inside && let Some(rest) = line.trim_start().strip_prefix("const ") {
            kinds.push(rest.split(':').next().unwrap_or("").trim().to_string());
        }
    }
    Some(TooltipInfo {
        kinds,
        data_system: own.text.contains("declare namespace C_TooltipInfo"),
    })
}

/// The aura filter words a flavor's client accepts (`"!"` when it negates
/// words): its `AuraFilterWord` type.
pub fn aura_filter_words(flavor: &str) -> Option<Vec<String>> {
    let [_, own] = declarations(flavor)?;
    let line = own
        .text
        .lines()
        .find_map(|l| l.strip_prefix("type AuraFilterWord = "))?;
    Some(
        line.split('|')
            .map(|w| w.trim().trim_matches('"').to_string())
            .filter(|w| !w.is_empty())
            .collect(),
    )
}

/// Whether a flavor's client has the engine's aura containers
/// (`CreateFrame("AuraContainer", …)`).
pub fn has_aura_containers(flavor: &str) -> bool {
    const LINE: &str = "declare global AuraContainerAuraGroupManagerMixin";
    let name = &LINE["declare global ".len()..];
    declarations(flavor).is_some_and(|[_, own]| {
        own.text.contains(LINE) || own.globals.iter().any(|g| g.name.starts_with(name))
    })
}

/// The APIs a declaration file declares: global functions and globals
/// (`Name`), namespaces and their members (`Namespace.Member`), and the
/// members of globals a class of the file types (`Global.member`, see
/// [`declared_names_of`]).
pub fn declared_names(text: &str) -> HashSet<String> {
    declared_names_of(&[text])
}

/// The APIs declaration texts declare together, as [`declared_names`]: a
/// global typed by classes (`declare global ChatFrameUtil: ChatFrameUtil`,
/// `EditModeManagerFrameMixin & ResizeLayoutMixin & Frame`) has their
/// members, and those of the classes they extend, from any of the texts. A
/// global whose type says nothing of its members (`unknown`) gives
/// `Global.*`: it may have any ([`has_api`]).
pub fn declared_names_of(texts: &[&str]) -> HashSet<String> {
    let mut out = HashSet::new();
    // class → its members and the classes it extends
    let mut classes: HashMap<String, (Vec<String>, Vec<String>)> = HashMap::new();
    // global → the parts of its type
    let mut typed: Vec<(String, Vec<String>)> = Vec::new();
    for text in texts {
        scan(text, &mut out, &mut classes, &mut typed);
    }
    for (global, parts) in typed {
        let mut seen = HashSet::new();
        let mut todo: Vec<&str> = Vec::new();
        for part in &parts {
            match part.as_str() {
                "unknown" | "any" | "table" => {
                    out.insert(format!("{global}.*"));
                }
                _ => todo.push(part),
            }
        }
        while let Some(class) = todo.pop() {
            if !seen.insert(class) {
                continue;
            }
            // Types the texts don't declare (widgets) list no members.
            let Some((members, bases)) = classes.get(class) else {
                continue;
            };
            for m in members {
                out.insert(format!("{global}.{m}"));
            }
            todo.extend(bases.iter().map(String::as_str));
        }
    }
    out
}

/// Whether `names` ([`declared_names_of`], [`flavor_names`]) has `api`
/// (`Name`, `C_X.F`, `Global.member`), or its global may have any member.
pub fn has_api(names: &HashSet<String>, api: &str) -> bool {
    names.contains(api)
        || api
            .split_once('.')
            .is_some_and(|(root, _)| names.contains(&format!("{root}.*")))
}

/// A flavor's APIs: [`declared_names_of`] its own and the shared
/// declarations, with their globals of a primitive type (`any` and `table`
/// ones may have any member). Computed once: the declarations are embedded.
pub fn flavor_names(flavor: &str) -> Option<&'static HashSet<String>> {
    use std::sync::{LazyLock, OnceLock};
    // One cell per flavor of the flavor table, in its order.
    static NAMES: LazyLock<Vec<OnceLock<HashSet<String>>>> = LazyLock::new(|| {
        let flavors = &wowlua_flavors::table().flavors;
        flavors.iter().map(|_| OnceLock::new()).collect()
    });
    let at = wowlua_flavors::table()
        .flavors
        .iter()
        .position(|f| f.id == flavor)?;
    Some(NAMES[at].get_or_init(|| {
        let files = declarations(flavor).expect("every flavor of the table has declarations");
        let mut names = declared_names_of(&[files[0].text, files[1].text]);
        for g in files.iter().flat_map(|f| f.globals.iter()) {
            names.insert(g.name.to_string());
            if matches!(g.ty, Prim::Any | Prim::Table) {
                names.insert(format!("{}.*", g.name));
            }
        }
        names
    }))
}

/// One text's names into `out`, its classes and its globals' types.
fn scan(
    text: &str,
    out: &mut HashSet<String>,
    classes: &mut HashMap<String, (Vec<String>, Vec<String>)>,
    typed: &mut Vec<(String, Vec<String>)>,
) {
    let ident = |s: &str| -> String {
        s.chars()
            .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
            .collect()
    };
    let mut namespace: Option<String> = None;
    let mut class: Option<String> = None;
    for line in text.lines() {
        if let Some(rest) = line
            .strip_prefix("declare function ")
            .or_else(|| line.strip_prefix("@deprecated declare function "))
        {
            out.insert(ident(rest));
        } else if let Some(rest) = line.strip_prefix("declare global ") {
            let name = ident(rest);
            // `Name: A & B`: types by name (a function type has no members).
            if let Some(ty) = rest[name.len()..].strip_prefix(": ") {
                let parts: Vec<String> = ty.split(" & ").map(str::trim).map(String::from).collect();
                if parts.iter().all(|p| !p.is_empty() && ident(p) == *p) {
                    typed.push((name.clone(), parts));
                }
            }
            out.insert(name);
        } else if let Some(rest) = line.strip_prefix("declare event ") {
            // Events by `event:NAME`, apart from globals of the same name.
            out.insert(format!("event:{}", ident(rest)));
        } else if let Some(rest) = line.strip_prefix("declare namespace ") {
            let ns = ident(rest);
            out.insert(ns.clone());
            namespace = Some(ns);
        } else if let Some(rest) = line.strip_prefix("declare class ") {
            let name = ident(rest);
            let bases = rest[name.len()..]
                .trim_start()
                .strip_prefix("extends ")
                .map(|b| b.split(',').map(|b| ident(b.trim())).collect())
                .unwrap_or_default();
            classes.entry(name.clone()).or_default().1 = bases;
            class = Some(name);
        } else if line == "end" {
            namespace = None;
            class = None;
        } else if let Some(member) = line.strip_prefix("    ")
            && !member.starts_with(' ')
            && !member.starts_with("---")
            && (namespace.is_some() || class.is_some())
        {
            let mut member = member.strip_prefix("@deprecated ").unwrap_or(member);
            for prefix in ["static ", "readonly ", "function ", "namespace ", "const "] {
                member = member.strip_prefix(prefix).unwrap_or(member);
            }
            let name = ident(member);
            if name.is_empty() {
                continue;
            }
            if let Some(ns) = &namespace {
                out.insert(format!("{ns}.{name}"));
            } else if let Some(c) = &class {
                classes.entry(c.clone()).or_default().0.push(name);
            }
        }
    }
}

/// A flavor's API documentation as the engine reads it: Blizzard's
/// documentation tables as gzipped JSON, every key kept (decision T199).
pub fn documentation(flavor: &str) -> Option<&'static [u8]> {
    Some(match flavor {
        "standard" => include_bytes!("../data/standard.api.json.gz"),
        "camelot" => include_bytes!("../data/camelot.api.json.gz"),
        "tbc" => include_bytes!("../data/tbc.api.json.gz"),
        "mists" => include_bytes!("../data/mists.api.json.gz"),
        "vanilla" => include_bytes!("../data/vanilla.api.json.gz"),
        _ => return None,
    })
}

#[cfg(test)]
mod tests {

    /// The parsed texts are the files in `data/` with the table's globals
    /// (and their `@onDemand` lines) replaced by spaces, and nothing else.
    #[test]
    fn padded_texts_keep_every_other_byte() {
        let names = ["shared", "camelot", "standard", "vanilla", "tbc", "mists"];
        for name in names {
            let file = if name == "shared" {
                super::shared()
            } else {
                super::own(name).unwrap()
            };
            let path = format!("{}/data/{name}.d.wowlua", env!("CARGO_MANIFEST_DIR"));
            let pristine = std::fs::read_to_string(path).unwrap();
            assert_eq!(file.text.len(), pristine.len(), "{name}");
            let mut expected = Vec::new();
            for g in file.globals.iter() {
                if let Some(addon) = g.on_demand {
                    expected.push(format!("@onDemand({addon:?})"));
                }
                let ty = format!("{:?}", g.ty).to_ascii_lowercase();
                expected.push(format!("declare global {}: {ty}", g.name));
            }
            let mut removed = Vec::new();
            for (p, t) in pristine
                .split_inclusive('\n')
                .zip(file.text.split_inclusive('\n'))
            {
                if p == t {
                    continue;
                }
                let body = p.trim_end_matches(['\r', '\n']);
                assert_eq!(&t[..body.len()], " ".repeat(body.len()), "{name}: {p:?}");
                assert_eq!(&t[body.len()..], &p[body.len()..], "{name}: line ends");
                removed.push(body.to_string());
            }
            assert_eq!(removed, expected, "{name}");
            assert_eq!(file.globals.len(), file.globals.iter().count());
        }
    }

    #[test]
    fn aura_filter_words_and_containers() {
        let camelot = super::aura_filter_words("camelot").unwrap();
        assert!(camelot.iter().any(|w| w == "!") && camelot.iter().any(|w| w == "DISPELLABLE"));
        let vanilla = super::aura_filter_words("vanilla").unwrap();
        assert!(!vanilla.iter().any(|w| w == "!") && vanilla.iter().any(|w| w == "HARMFUL"));
        assert!(super::has_aura_containers("camelot") && super::has_aura_containers("standard"));
        assert!(!super::has_aura_containers("vanilla"));
    }

    #[test]
    fn tooltip_kinds_and_data_system() {
        let camelot = super::tooltip_info("camelot").unwrap();
        assert!(camelot.data_system);
        assert!(
            ["Item", "Spell", "Unit", "Mount"]
                .iter()
                .all(|k| camelot.kinds.iter().any(|x| x == k))
        );
        let vanilla = super::tooltip_info("vanilla").unwrap();
        assert!(!vanilla.data_system);
        assert!(super::tooltip_info("nope").is_none());
    }

    #[test]
    fn names() {
        let names = super::declared_names(
            "declare function GetTime(): number\ndeclare namespace C_X\n    function Do()\n    value: number\nend\ndeclare global UIParent: Frame\n",
        );
        for n in ["GetTime", "C_X", "C_X.Do", "C_X.value", "UIParent"] {
            assert!(names.contains(n), "{n}: {names:?}");
        }
        assert!(super::declarations("standard").is_some());
    }

    /// The members of a global typed by a class (`declare global U: U`),
    /// through an intersection and the classes extended, in the same text
    /// or another; a class no global has gives none.
    #[test]
    fn class_members_of_globals() {
        let names = super::declared_names(
            "declare class U\n    function A()\n    --- doc\n    b: number\n    static function C(): boolean\n    @deprecated function D()\n        nested: number\nend\ndeclare global U: U\ndeclare class P\n    function Q()\nend\n",
        );
        for n in ["U", "U.A", "U.b", "U.C", "U.D"] {
            assert!(names.contains(n), "{n}: {names:?}");
        }
        assert!(!names.contains("U.nested") && !names.contains("P.Q") && !names.contains("U.doc"));
        let names = super::declared_names_of(&[
            "declare global X: M & Frame\ndeclare global O: unknown\n",
            "declare class M extends B\n    function F()\nend\ndeclare class B\n    function G()\nend\n",
        ]);
        for n in ["X.F", "X.G"] {
            assert!(names.contains(n), "{n}: {names:?}");
        }
        // A global whose type says nothing of its members may have any.
        assert!(super::has_api(&names, "O.Anything") && super::has_api(&names, "X.F"));
        assert!(!super::has_api(&names, "X.H") && !super::has_api(&names, "Y"));
    }

    /// Each flavor's APIs, the shared declarations' globals typed by its
    /// classes included (`ChatFrameUtil`), and its globals of a primitive
    /// type.
    #[test]
    fn flavor_names() {
        let standard = super::flavor_names("standard").unwrap();
        let tbc = super::flavor_names("tbc").unwrap();
        let mists = super::flavor_names("mists").unwrap();
        assert!(super::has_api(tbc, "ChatFrameUtil.ForEachChatFrame"));
        assert!(!super::has_api(tbc, "ChatFrameUtil.NoSuchFunction"));
        assert!(super::has_api(standard, "AddonCompartmentFrame"));
        assert!(!super::has_api(tbc, "AddonCompartmentFrame"));
        assert!(super::has_api(mists, "ChatFrameUtil.SendTell"));
        assert!(super::has_api(
            tbc,
            "EditModeManagerFrame.GetActiveLayoutInfo"
        ));
        // a global of a primitive type (taken out of the parsed text)
        assert!(super::has_api(tbc, "CurveConstants"));
        assert!(super::has_api(tbc, "CurveConstants.ScaleTo100"));
        assert!(super::has_api(mists, "CurveConstants.ScaleTo100"));
        assert!(super::has_api(
            mists,
            "EditModeManagerFrame.GetActiveLayoutInfo"
        ));
        assert!(super::flavor_names("nope").is_none());
        assert!(super::flavor_names("cata").is_none());
    }

    /// Every flavor of the flavor table has declarations and documentation,
    /// and only those (the build script's list and the matches agree).
    #[test]
    fn every_flavor_of_the_table() {
        let table = wowlua_flavors::table();
        for flavor in &table.flavors {
            assert!(super::own(&flavor.id).is_some(), "{}", flavor.id);
            assert!(super::documentation(&flavor.id).is_some(), "{}", flavor.id);
        }
        for gone in ["cata", "wrath"] {
            assert!(super::own(gone).is_none() && super::documentation(gone).is_none());
        }
    }
}
